style.css:
@-moz-document url-prefix("https://drive.google.com/drive/") {
/* Tło całej strony na jasno różowe */
  html, body, div#drive_main_page, div[jsname="aT2isf"] {
    background-color: #f9d6e4 !important;
  }

  /* Pasek boczny (lewe menu) */
  div[jscontroller="uY3lWb"] {
    background-color: #f4a6c2 !important;
  }

  /* Pasek górny (header) */
  div[jsname="haAclf"], div[jsname="rWL6oc"] {
    background-color: #f4a6c2 !important;
  }

  /* Przyciski nawigacyjne */
  div[jsname="haAclf"] div {
    background-color: #f9d6e4 !important;
    color: #333 !important;
  }

  /* Podświetlenie aktywnego folderu */
  div[role="treeitem"][aria-selected="true"] {
    background-color: #f28b98 !important; /* Ciemniejszy różowy dla aktywnego folderu */
    color: white !important; /* Biały kolor tekstu */
  }

  /* Ikony folderów */
  div[role="gridcell"] {
    background-color: #f9d6e4 !important;
  }

  /* Linki i tekst */
  a, span {
    color: #d16b8c !important;
  }
}
